import json
d = json.load(open('/workspace/contracts/openapi.contract.json'))
# Check the operations_state schema, plus a few key ops
for op_id in ['read_operations_state', 'create_location', 'create_collection_request', 'check_serviceability', 'create_user', 'select_active_role', 'list_role_work']:
    p = None
    for path, methods in d['paths'].items():
        if op_id in [methods[m].get('operationId') for m in methods]:
            p = path
            break
    if p:
        op = d['paths'][p]['post'] if 'post' in d['paths'][p] else list(d['paths'][p].values())[0]
        print(f'\n=== {op_id} at {p} ===')
        print('requestBody:', json.dumps(op.get('requestBody', {}).get('content', {}).get('application/json', {}).get('schema', {}), indent=2)[:2000])
        print('responses 200:', json.dumps(op.get('responses', {}).get('200', {}).get('content', {}).get('application/json', {}).get('schema', {}), indent=2)[:1500])
EOF"}

