-- Lab Sample Pickup & Delivery — schema bootstrap.
-- Idempotent: tables, types, and indexes are created with IF NOT EXISTS / DO blocks.

-- Enums ----------------------------------------------------------------------
DO $$ BEGIN
    CREATE TYPE role_t AS ENUM (
        'administrator','dispatcher','requester',
        'certified_collection_professional','relay_courier',
        'node_handler','laboratory_intake_operator'
    );
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

DO $$ BEGIN
    CREATE TYPE location_function_t AS ENUM (
        'collection_point','transfer_point','hub','laboratory'
    );
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

DO $$ BEGIN
    CREATE TYPE assignment_status_t AS ENUM (
        'offered','accepted','declined','expired',
        'at_pickup','picked_up','in_transit','arrived',
        'in_progress','completed','cancelled','rejected'
    );
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

DO $$ BEGIN
    CREATE TYPE assignment_kind_t AS ENUM (
        'collection','transport','node_handling','laboratory_intake'
    );
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

DO $$ BEGIN
    CREATE TYPE sample_status_t AS ENUM (
        'requested','awaiting_collection','sealed',
        'awaiting_handoff','in_transit','at_node','delivered_to_node',
        'at_laboratory','received','exception','expired','cancelled'
    );
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

DO $$ BEGIN
    CREATE TYPE handoff_state_t AS ENUM (
        'pending','sender_confirmed','completed','cancelled'
    );
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

DO $$ BEGIN
    CREATE TYPE exception_kind_t AS ENUM (
        'handling_noncompliant','capacity_unavailable','refrigeration_lost',
        'container_damaged','sample_lost','no_qualified_worker','overdue',
        'rejected_at_lab','other'
    );
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

DO $$ BEGIN
    CREATE TYPE journey_status_t AS ENUM (
        'planning','active','replaced','cancelled','completed','expired'
    );
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

DO $$ BEGIN
    CREATE TYPE capacity_kind_t AS ENUM ('regular','cooled');
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

DO $$ BEGIN
    CREATE TYPE capacity_resource_t AS ENUM ('node','laboratory','connection');
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

DO $$ BEGIN
    CREATE TYPE replan_status_t AS ENUM (
        'replaced','exception','expired','not_required'
    );
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

-- Tables ---------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS users (
    user_id            UUID PRIMARY KEY,
    username           TEXT UNIQUE NOT NULL,
    email              TEXT NOT NULL DEFAULT '',
    full_name          TEXT NOT NULL DEFAULT '',
    phone              TEXT NOT NULL DEFAULT '',
    password_hash      TEXT NOT NULL,
    roles              role_t[] NOT NULL DEFAULT '{}',
    qualifications     TEXT[] NOT NULL DEFAULT '{}',
    assigned_location  UUID,
    available          BOOLEAN NOT NULL DEFAULT TRUE,
    capacity_units     INT NOT NULL DEFAULT 1,
    last_location_lng  DOUBLE PRECISION,
    last_location_lat  DOUBLE PRECISION,
    last_location_at   TIMESTAMPTZ,
    active             BOOLEAN NOT NULL DEFAULT TRUE,
    created_at         TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS certifications (
    user_id  UUID NOT NULL REFERENCES users(user_id) ON DELETE CASCADE,
    name     TEXT NOT NULL,
    active   BOOLEAN NOT NULL DEFAULT TRUE,
    PRIMARY KEY(user_id, name)
);

CREATE TABLE IF NOT EXISTS sessions (
    token         TEXT PRIMARY KEY,
    user_id       UUID NOT NULL REFERENCES users(user_id) ON DELETE CASCADE,
    active_role   role_t NOT NULL,
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    last_seen     TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS sample_types (
    sample_type_id            UUID PRIMARY KEY,
    name                      TEXT UNIQUE NOT NULL,
    qualified_collector_required BOOLEAN NOT NULL DEFAULT FALSE,
    required_qualification    TEXT NOT NULL DEFAULT '',
    container_type            TEXT NOT NULL DEFAULT '',
    temperature_min_c         DOUBLE PRECISION NOT NULL DEFAULT -100,
    temperature_max_c         DOUBLE PRECISION NOT NULL DEFAULT 100,
    incompatible_sample_types UUID[] NOT NULL DEFAULT '{}',
    requires_cooled_route     BOOLEAN NOT NULL DEFAULT FALSE,
    batching_allowed          BOOLEAN NOT NULL DEFAULT TRUE,
    active                    BOOLEAN NOT NULL DEFAULT TRUE,
    created_at                TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS locations (
    location_id      UUID PRIMARY KEY,
    name             TEXT NOT NULL,
    lng              DOUBLE PRECISION NOT NULL,
    lat              DOUBLE PRECISION NOT NULL,
    coverage_km      DOUBLE PRECISION NOT NULL DEFAULT 5.0,
    handling_minutes INT NOT NULL DEFAULT 0,
    active           BOOLEAN NOT NULL DEFAULT TRUE,
    functions        location_function_t[] NOT NULL DEFAULT '{}',
    is_laboratory    BOOLEAN NOT NULL DEFAULT FALSE,
    accepts_sample_types UUID[] NOT NULL DEFAULT '{}',
    created_at       TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS location_functions (
    location_id UUID NOT NULL REFERENCES locations(location_id) ON DELETE CASCADE,
    function    location_function_t NOT NULL,
    active      BOOLEAN NOT NULL DEFAULT TRUE,
    PRIMARY KEY (location_id, function)
);

CREATE TABLE IF NOT EXISTS connections (
    connection_id   UUID PRIMARY KEY,
    from_location   UUID NOT NULL REFERENCES locations(location_id),
    to_location     UUID NOT NULL REFERENCES locations(location_id),
    travel_minutes  INT NOT NULL,
    mode            TEXT NOT NULL DEFAULT 'road',
    capacity_units  INT NOT NULL DEFAULT 0,
    cooled_capacity_units INT NOT NULL DEFAULT 0,
    active          BOOLEAN NOT NULL DEFAULT TRUE,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS capacity (
    resource_kind  capacity_resource_t NOT NULL,
    resource_id    UUID NOT NULL,
    kind           capacity_kind_t NOT NULL,
    configured     INT NOT NULL DEFAULT 0,
    reserved       INT NOT NULL DEFAULT 0,
    PRIMARY KEY (resource_kind, resource_id, kind)
);

CREATE TABLE IF NOT EXISTS samples (
    sample_id             UUID PRIMARY KEY,
    requester_id          UUID REFERENCES users(user_id),
    sample_type_id        UUID NOT NULL REFERENCES sample_types(sample_type_id),
    origin_kind           TEXT NOT NULL,                       -- home|clinic|node
    origin_node_id        UUID REFERENCES locations(location_id),
    origin_lng            DOUBLE PRECISION,
    origin_lat            DOUBLE PRECISION,
    collection_window_start TIMESTAMPTZ,
    collection_window_end   TIMESTAMPTZ,
    delivery_deadline     TIMESTAMPTZ NOT NULL,
    sealed_at             TIMESTAMPTZ,
    collected_at          TIMESTAMPTZ,
    observed_container    TEXT,
    observed_temperature  DOUBLE PRECISION,
    handling_compliant    BOOLEAN NOT NULL DEFAULT TRUE,
    status                sample_status_t NOT NULL DEFAULT 'requested',
    current_holder_id     UUID,
    current_holder_kind   TEXT,
    container_type        TEXT,
    active                BOOLEAN NOT NULL DEFAULT TRUE,
    created_at            TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at            TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_samples_requester ON samples(requester_id);
CREATE INDEX IF NOT EXISTS idx_samples_status ON samples(status);

CREATE TABLE IF NOT EXISTS journeys (
    journey_id          UUID PRIMARY KEY,
    plan_version        INT NOT NULL DEFAULT 1,
    parent_journey_id   UUID REFERENCES journeys(journey_id),
    status              journey_status_t NOT NULL DEFAULT 'planning',
    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    replan_status       replan_status_t,
    replan_note         TEXT
);

CREATE TABLE IF NOT EXISTS journey_samples (
    journey_id  UUID NOT NULL REFERENCES journeys(journey_id) ON DELETE CASCADE,
    sample_id   UUID NOT NULL REFERENCES samples(sample_id) ON DELETE CASCADE,
    PRIMARY KEY (journey_id, sample_id)
);

CREATE TABLE IF NOT EXISTS journey_legs (
    leg_id              UUID PRIMARY KEY,
    journey_id          UUID NOT NULL REFERENCES journeys(journey_id) ON DELETE CASCADE,
    leg_index           INT NOT NULL,
    kind                assignment_kind_t NOT NULL,
    from_location_id    UUID REFERENCES locations(location_id),
    to_location_id      UUID REFERENCES locations(location_id),
    worker_id           UUID REFERENCES users(user_id),
    requires_cooled     BOOLEAN NOT NULL DEFAULT FALSE,
    estimated_minutes   INT NOT NULL DEFAULT 0,
    completed           BOOLEAN NOT NULL DEFAULT FALSE,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_legs_journey ON journey_legs(journey_id);
CREATE INDEX IF NOT EXISTS idx_legs_worker ON journey_legs(worker_id);

CREATE TABLE IF NOT EXISTS assignments (
    assignment_id      UUID PRIMARY KEY,
    leg_id             UUID NOT NULL REFERENCES journey_legs(leg_id) ON DELETE CASCADE,
    sample_id          UUID NOT NULL REFERENCES samples(sample_id) ON DELETE CASCADE,
    worker_id          UUID REFERENCES users(user_id),
    location_id        UUID REFERENCES locations(location_id),
    required_qualification TEXT NOT NULL DEFAULT '',
    status             assignment_status_t NOT NULL DEFAULT 'offered',
    offered_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
    accepted_at        TIMESTAMPTZ,
    completed_at       TIMESTAMPTZ,
    last_status_event  TEXT,
    last_status_at     TIMESTAMPTZ,
    offer_seq          BIGINT NOT NULL DEFAULT 1,
    UNIQUE (assignment_id)
);
CREATE INDEX IF NOT EXISTS idx_assign_worker_status ON assignments(worker_id, status);
CREATE INDEX IF NOT EXISTS idx_assign_leg ON assignments(leg_id);
CREATE INDEX IF NOT EXISTS idx_assign_sample ON assignments(sample_id);

CREATE TABLE IF NOT EXISTS handoffs (
    handoff_id        UUID PRIMARY KEY,
    sample_id         UUID NOT NULL REFERENCES samples(sample_id),
    from_assignment   UUID NOT NULL REFERENCES assignments(assignment_id),
    to_assignment     UUID NOT NULL REFERENCES assignments(assignment_id),
    sender_id         UUID NOT NULL REFERENCES users(user_id),
    receiver_id       UUID NOT NULL REFERENCES users(user_id),
    initiated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    sender_confirmed_at TIMESTAMPTZ,
    receiver_confirmed_at TIMESTAMPTZ,
    completed_at      TIMESTAMPTZ,
    state             handoff_state_t NOT NULL DEFAULT 'pending'
);
CREATE INDEX IF NOT EXISTS idx_handoffs_sample ON handoffs(sample_id);
CREATE UNIQUE INDEX IF NOT EXISTS uq_handoff_active
    ON handoffs(sample_id, from_assignment, to_assignment)
    WHERE state IN ('pending','sender_confirmed');

CREATE TABLE IF NOT EXISTS idempotency (
    key           TEXT PRIMARY KEY,
    scope         TEXT NOT NULL,
    request_hash  TEXT NOT NULL,
    response_body JSONB NOT NULL,
    status_code   INT NOT NULL,
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS audit_log (
    id           BIGSERIAL PRIMARY KEY,
    occurred_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    actor_id     UUID,
