	"path/filepath"
	"time"

	"github.com/example/labspd/internal/auth"
	"github.com/example/labspd/internal/config"
	"github.com/example/labspd/internal/handlers"
	"github.com/example/labspd/internal/realtime"
	"github.com/example/labspd/internal/seed"
	"github.com/example/labspd/internal/store"
	"github.com/go-chi/chi/v5"
	"github.com/go-chi/chi/v5/middleware"
	"github.com/jackc/pgx/v5/pgxpool"
)

func main() {
	cfg := config.Load()

	pool, err := pgxpool.New(context.Background(), cfg.DatabaseURL)
	if err != nil {
		log.Fatalf("pg connect: %v", err)
	}
	defer pool.Close()

	if err := store.Bootstrap(context.Background(), pool, filepath.Join(cfg.MigrationsDir)); err != nil {
		log.Fatalf("bootstrap: %v", err)
	}

	if err := seed.SeedDefaults(context.Background(), pool, cfg.AdminUsername, cfg.AdminPassword); err != nil {
		log.Fatalf("seed: %v", err)
	}

	bus := realtime.NewBus(pool)
	authSvc := auth.NewService(pool)

	r := chi.NewRouter()
	r.Use(middleware.Recoverer)
	r.Use(corsMW)

	handlers.Mount(r, pool, bus, authSvc)

	addr := ":8080"
	log.Printf("listening on %s", addr)
	srv := &http.Server{
		Addr:              addr,
		Handler:           r,
		ReadHeaderTimeout: 10 * time.Second,
	}
	if err := srv.ListenAndServe(); err != nil {
		log.Fatal(err)
	}
}

func corsMW(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Access-Control-Allow-Origin", "*")
		w.Header().Set("Access-Control-Allow-Methods", "GET,POST,OPTIONS")
		w.Header().Set("Access-Control-Allow-Headers", "Content-Type,Authorization,Idempotency-Key")
		if r.Method == http.MethodOptions {
			w.WriteHeader(204)
			return
		}
		next.ServeHTTP(w, r)
	})
}

