package config

import (
	"os"
	"path/filepath"
)

type Config struct {
	DatabaseURL    string
	AdminUsername  string
	AdminPassword  string
	MigrationsDir  string
	FrontendDir    string
}

func Load() Config {
	root := projectRoot()
	c := Config{
		DatabaseURL:   envOr("DATABASE_URL", "postgresql://arena:arena@127.0.0.1:5432/arena?sslmode=disable"),
		AdminUsername: envOr("ADMIN_USERNAME", "admin"),
		AdminPassword: envOr("ADMIN_PASSWORD", "admin"),
		MigrationsDir: filepath.Join(root, "backend", "migrations"),
		FrontendDir:   filepath.Join(root, "frontend", "dist"),
	}
	return c
}

func envOr(k, def string) string {
	if v := os.Getenv(k); v != "" {
		return v
	}
	return def
}

// projectRoot returns the absolute path to /workspace by walking up
// from the executable until a directory containing "backend" is found
// or falling back to the env var WORKSPACE_ROOT or /workspace.
func projectRoot() string {
	if v := os.Getenv("WORKSPACE_ROOT"); v != "" {
		return v
	}
	wd, err := os.Getwd()
	if err == nil {
		dir := wd
		for i := 0; i < 8; i++ {
			if _, err := os.Stat(filepath.Join(dir, "backend")); err == nil {
				return dir
			}
			parent := filepath.Dir(dir)
			if parent == dir {
				break
			}
			dir = parent
		}
	}
	return "/workspace"
}

