// Package seed ensures that an empty database contains the four named sample
// types (Amber, Indigo, Frost, Pulse), a default collection point, hub and
// laboratory, and (on first run only) the initial administrator account.
package seed

import (
	"context"
	"errors"
	"strings"

	"github.com/example/labspd/internal/auth"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
)

// SeedDefaults is idempotent. It only creates the initial admin account when
// the users table is empty.
func SeedDefaults(ctx context.Context, pool *pgxpool.Pool, adminUsername, adminPassword string) error {
	if err := ensureSampleTypes(ctx, pool); err != nil {
		return err
	}
	if err := ensureDefaultLocations(ctx, pool); err != nil {
		return err
	}
	if err := ensureDefaultCapacities(ctx, pool); err != nil {
		return err
	}
	if err := ensureAdmin(ctx, pool, adminUsername, adminPassword); err != nil {
		return err
	}
	if err := ensureDispatcherSeed(ctx, pool); err != nil {
		return err
	}
	return nil
}

func ensureSampleTypes(ctx context.Context, pool *pgxpool.Pool) error {
	type def struct {
		name      string
		container string
		minC      float64
		maxC      float64
		qualReq   bool
		qual      string
		cooled    bool
		batch     bool
	}
	for _, d := range []def{
		{"Amber", "amber_vial", 0, 25, true, "amber", false, true},
		{"Indigo", "indigo_tube", 0, 25, true, "indigo", false, true},
		{"Frost", "frost_cooler", -80, 8, true, "frost", true, true},
		{"Pulse", "pulse_shipper", 0, 25, true, "pulse", false, false},
	} {
		var id string
		err := pool.QueryRow(ctx, `
			INSERT INTO sample_types (sample_type_id, name, qualified_collector_required, required_qualification,
			                          container_type, temperature_min_c, temperature_max_c, requires_cooled_route, batching_allowed)
			VALUES (gen_random_uuid(), $1, $2, $3, $4, $5, $6, $7, $8)
			ON CONFLICT (name) DO UPDATE SET qualified_collector_required = EXCLUDED.qualified_collector_required
			RETURNING sample_type_id`, d.name, d.qualReq, d.qual, d.container, d.minC, d.maxC, d.cooled, d.batch).Scan(&id)
		if err != nil {
			return err
		}
		_ = id
	}
	// Set incompatibilities: Amber and Indigo cannot share containers.
	_, err := pool.Exec(ctx, `
		UPDATE sample_types st SET incompatible_sample_types = (
			SELECT COALESCE(array_agg(other.sample_type_id), '{}')::uuid[]
			FROM sample_types other
			WHERE other.name IN ('Indigo') AND st.name = 'Amber'
		) WHERE st.name = 'Amber'`)
	if err != nil {
		return err
	}
	_, err = pool.Exec(ctx, `
		UPDATE sample_types st SET incompatible_sample_types = (
			SELECT COALESCE(array_agg(other.sample_type_id), '{}')::uuid[]
			FROM sample_types other
			WHERE other.name IN ('Amber') AND st.name = 'Indigo'
		) WHERE st.name = 'Indigo'`)
	return err
}

func ensureDefaultLocations(ctx context.Context, pool *pgxpool.Pool) error {
	type def struct {
		name       string
		lng, lat   float64
		coverage   float64
		handling   int
		functions  []string
		lab        bool
		accepts    []string
	}
	defaults := []def{
		{"Central Clinic", -73.99, 40.74, 5.0, 5,
			[]string{"collection_point", "transfer_point"}, false, []string{}},
		{"Riverside Collection Point", -73.96, 40.78, 5.0, 5,
			[]string{"collection_point"}, false, []string{}},
		{"Midtown Hub", -73.98, 40.76, 5.0, 10,
			[]string{"transfer_point", "hub"}, false, []string{}},
		{"Northern Hub", -73.95, 40.80, 5.0, 10,
			[]string{"transfer_point", "hub"}, false, []string{}},
		{"Downtown Laboratory", -73.99, 40.75, 5.0, 15,
			[]string{"laboratory", "transfer_point", "hub"}, true,
			[]string{"Amber", "Indigo", "Frost", "Pulse"}},
		{"Eastside Laboratory", -73.93, 40.77, 5.0, 15,
			[]string{"laboratory", "transfer_point"}, true,
			[]string{"Amber", "Indigo", "Pulse"}},
	}
	ids := map[string]string{}
	for _, d := range defaults {
		var id string
		err := pool.QueryRow(ctx, `
			INSERT INTO locations (location_id, name, lng, lat, coverage_km, handling_minutes,
			                       is_laboratory, functions, accepts_sample_types, active)
			VALUES (gen_random_uuid(), $1, $2, $3, $4, $5, $6, $7::location_function_t[],
			        COALESCE((SELECT array_agg(st.sample_type_id) FROM sample_types st WHERE st.name = ANY($8)), '{}')::uuid[],
			        TRUE)
			ON CONFLICT DO NOTHING
			RETURNING location_id`, d.name, d.lng, d.lat, d.coverage, d.handling, d.lab,
			stringsToArray(d.functions), d.accepts).Scan(&id)
		if err != nil && !errors.Is(err, pgx.ErrNoRows) {
			return err
		}
		if id == "" {
			_ = pool.QueryRow(ctx, `SELECT location_id FROM locations WHERE name=$1`, d.name).Scan(&id)
		}
		ids[d.name] = id
		for _, f := range d.functions {
			_, err := pool.Exec(ctx, `INSERT INTO location_functions(location_id, function) VALUES ($1, $2)
				ON CONFLICT (location_id, function) DO UPDATE SET active=TRUE`, id, f)
			if err != nil {
				return err
			}
		}
	}
	// Default connections: clinic -> midtown -> downtown lab; riverside -> midtown -> downtown lab; etc.
	type conn struct{ from, to string; minutes, cap, cooled int }
	for _, c := range []conn{
		{"Central Clinic", "Midtown Hub", 8, 4, 2},
		{"Riverside Collection Point", "Midtown Hub", 12, 4, 2},
		{"Midtown Hub", "Downtown Laboratory", 12, 6, 3},
		{"Midtown Hub", "Eastside Laboratory", 18, 4, 2},
		{"Northern Hub", "Midtown Hub", 12, 4, 2},
		{"Northern Hub", "Eastside Laboratory", 16, 4, 2},
		{"Eastside Laboratory", "Downtown Laboratory", 24, 4, 2},
		{"Downtown Laboratory", "Midtown Hub", 16, 4, 2},
	} {
		fromID, ok1 := ids[c.from]
		toID, ok2 := ids[c.to]
		if !ok1 || !ok2 {
			continue
		}
		var id string
		err := pool.QueryRow(ctx, `
			INSERT INTO connections (connection_id, from_location, to_location, travel_minutes,
			                          capacity_units, cooled_capacity_units, active)
			VALUES (gen_random_uuid(), $1, $2, $3, $4, $5, TRUE)
			ON CONFLICT DO NOTHING
			RETURNING connection_id`, fromID, toID, c.minutes, c.cap, c.cooled).Scan(&id)
		if err != nil && !errors.Is(err, pgx.ErrNoRows) {
			return err
		}
		if id == "" {
			_ = pool.QueryRow(ctx, `SELECT connection_id FROM connections WHERE from_location=$1 AND to_location=$2`, fromID, toID).Scan(&id)
		}
		_, err = pool.Exec(ctx, `INSERT INTO capacity(resource_kind, resource_id, kind, configured, reserved)
			VALUES ('connection', $1, 'regular', $2, 0)
			ON CONFLICT (resource_kind, resource_id, kind) DO UPDATE SET configured=EXCLUDED.configured`,
			id, c.cap)
		if err != nil {
			return err
		}
		_, err = pool.Exec(ctx, `INSERT INTO capacity(resource_kind, resource_id, kind, configured, reserved)
			VALUES ('connection', $1, 'cooled', $2, 0)
			ON CONFLICT (resource_kind, resource_id, kind) DO UPDATE SET configured=EXCLUDED.configured`,
			id, c.cooled)
		if err != nil {
			return err
		}
	}
	// Per-location capacities
	for name, id := range ids {
		if id == "" {
			continue
		}
		_, err := pool.Exec(ctx, `INSERT INTO capacity(resource_kind, resource_id, kind, configured, reserved)
			VALUES ('node', $1, 'regular', 8, 0),
			       ('node', $1, 'cooled', 4, 0)
			ON CONFLICT (resource_kind, resource_id, kind) DO UPDATE SET configured = EXCLUDED.configured`, id)
		if err != nil {
			return err
		}
		_ = name
	}
	return nil
}

