import (
	"github.com/example/labspd/internal/auth"
	"github.com/example/labspd/internal/realtime"
	"github.com/go-chi/chi/v5"
	"github.com/jackc/pgx/v5/pgxpool"
)

// Mount registers every API route on r.
func Mount(r chi.Router, pool *pgxpool.Pool, bus *realtime.Bus, svc *auth.Service) {
	// Wire health & readiness for the /ready endpoint.
	r.Get("/ready", readiness(pool))

	r.Route("/api", func(api chi.Router) {
		api.Get("/realtime/events", realtimeEvents(bus))
		// Below this point, real handlers will be mounted. The placeholder
		// keeps the package compilable while the full implementation is
		// added incrementally in subsequent files.
	})
}

// placeholder no-op so the package compiles during scaffolding
func init() { _ = realtime.Bus(nil) }

