// Package store wires the PostgreSQL pool and runs schema migrations.
package store

import (
	"context"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"github.com/jackc/pgx/v5/pgxpool"
)

// Bootstrap creates schema if missing and runs all *.sql migrations.
func Bootstrap(ctx context.Context, pool *pgxpool.Pool, dir string) error {
	// Always run our base migration first; ensure idempotent.
	if err := execFile(ctx, pool, filepath.Join(dir, "0001_init.sql")); err != nil {
		return fmt.Errorf("migrate 0001: %w", err)
	}
	entries, err := os.ReadDir(dir)
	if err != nil {
		return err
	}
	var rest []string
	for _, e := range entries {
		if e.IsNil() || !strings.HasSuffix(e.Name(), ".sql") || e.Name() == "0001_init.sql" {
			continue
		}
		rest = append(rest, e.Name())
	}
	sort.Strings(rest)
	for _, name := range rest {
		if err := execFile(ctx, pool, filepath.Join(dir, name)); err != nil {
			return fmt.Errorf("migrate %s: %w", name, err)
		}
	}
	return nil
}

func execFile(ctx context.Context, pool *pgxpool.Pool, path string) error {
	b, err := os.ReadFile(path)
	if err != nil {
		if os.IsNotExist(err) {
			return nil
		}
		return err
	}
	if strings.TrimSpace(string(b)) == "" {
		return nil
	}
	_, err = pool.Exec(ctx, string(b))
	return err
}

